INSERT INTO video_impl_claims VALUES(15,'-VQhsvP6Giw','role',2,NULL,'fb_falseback',NULL,NULL,NULL,'「he frequently **tucks inside to form a temporary back three**」(그는 자주 **안으로 접혀 임시 백3를 만든다**)','HELD','⭐ T6 A/B의 원 가설이다(obs#700). ⛔ 그러나 26/27 **공식전** 실측은 `fb_att_wb/Support` .8919이고 `fb_falseback`은 상위 5위 밖이다(obs#773 — 종전에 wingback/Balanced로 보였던 것은 바이에른 친선 혼입 탓이었고 교정됐다). 또한 이 영상은 **25/26 체제**(마르티네스·오나나·로저스·틸레만스 XI)라 불변규칙 7로 26/27 처방 근거가 못 된다. ⇒ 처방 변경 없음. **재판정 조건: T6 A/B 실행** — 캐시 본인 그리드가 안쪽(열1~2)으로 이동하는지가 1차 판정이다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(16,'-VQhsvP6Giw','role',6,NULL,'fb_att_wb','Support',NULL,NULL,'「Maatsen on the left operates as a **support attacking wing back**」(좌측 마첸은 **서포트형 공격 윙백**으로 뛴다)','HELD','✅ 이미 일치 — `slot_canon_roles`(AVL 4-2-3-1 Wide LB) = `fb_att_wb/Support`. 영상이 독립 확인한 것이라 변경 없음. ⚠️ 재판정 조건: obs#768로 **해방 사이드가 좌→우로 뒤집혔다**(맥긴 RM winger·헤밍스 LM widemid) ⇒ C2/C6 재판정 시 LB 전진/절제가 함께 바뀔 수 있다(할 일 20).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(17,'-VQhsvP6Giw','role',16,NULL,'st_advanced','Versatile',NULL,NULL,'「set up as an **advanced forward with a flexible focus**」(**유동 포커스의 어드밴스드 포워드**로 세팅)','HELD','✅ 이미 일치 — `prescriptions#11` = `st_advanced/Versatile`(obs#12가 07-08의 Support 변경을 되돌린 값). 영상이 독립 수렴했다. 재판정 조건: 26/27 왓킨스 표본이 쌓여 기능 프로파일(xg/xa)이 바뀌면 재산출.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(18,'-VQhsvP6Giw','role',10,NULL,'wm_wideplm',NULL,NULL,NULL,'「McGinn prefers to **link play with the fullback**... operating **between the half spaces and wide areas**」(맥긴은 **풀백과의 연결 플레이를 선호**하며 **하프스페이스와 측면 사이**에서 움직인다)','REJECTED','⛔ **불변규칙 7 — 25/26 체제 자료다**(2025-12-08 게시, 마르티네스·오나나·로저스·틸레만스가 XI). 26/27 처방 근거로 쓰지 않는다. ⭐ 다만 **당시 우리 `role:season`도 `wm_wideplm/Attack` .761이었다**는 점에서 25/26 축에서는 정합했다 — obs#766의 26/27 교정(`wm_winger/Attack` .8119, Δ.0618 단독 확정)을 반증하지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(19,'-VQhsvP6Giw','limit',NULL,NULL,NULL,NULL,'set_pieces','세트피스 배치까지 지정한 외부 자료 — 공격 코너(오나나 타깃·왓킨스 니어런·토레스/콘사 백포스트)와 수비 코너(토레스 맨마킹·오나나 포스트 와처) 및 캐시 롱스로','「Amadu Onana is the primary aerial target with Watkins making the aggressive near post run」(오나나가 주 공중 타깃이고 왓킨스가 적극적인 니어포스트 러시를 한다)','REJECTED','⛔ `reproduction_limits`에 **`set_pieces` = 「세트피스 설계 축이 없다 — 키커·타깃 지정 수준」**으로 이미 등록돼 있다. FC26에 옮길 축이 없으므로 구현 주장으로 채택하지 않는다. ⭐ 다만 **실축 기록으로는 가치가 있다** — 세트피스 역할 배치를 명시한 유일한 자료다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(20,'MdhMmXmVdUc','team_axis',NULL,'CHE',NULL,NULL,'defensive_approach','High','「the team''s approach is **set to high**, with the manager demanding an aggressive press」(팀 접근은 **하이**로 설정되고 감독은 적극적 압박을 요구한다)','HELD','✅ 이미 일치 — `team_tactic_setups` regime 2 `reference`(알론소 블루프린트) = da=High · line=64. ⚠️ 단 같은 regime의 `projected` 행은 da=Balanced로 갈려 있고, gVmb3JTFcKU(Tactical Analysis)는 **시즌 개막 후 압박이 콤팩트해졌다**고 관측했다. ⇒ 재판정 조건: 공식전 3경기 이상 쌓이면 High ↔ Balanced 중 어느 쪽이 정본인지 확정.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(21,'MdhMmXmVdUc','team_axis',NULL,'CHE',NULL,NULL,'build_up_style','Balanced','「The **build-up style is set to balanced**, allowing the team to adapt their approach depending on the opposition''s press」(**빌드업 스타일은 밸런스드**로 설정해 상대 압박에 따라 조절한다)','PENDING','⭐ 팀 설정 3축은 실측이 값을 갖지 않는 축이라 전술 분석이 1차 소스다(docs/30 7단계). 현행 regime 2는 `Short Passing`(projected·reference 둘 다)인데 이 자료는 **Balanced**, gVmb3JTFcKU는 실측 근거로 **Counter**(146패스·점유 25.6%)를 지지한다 ⇒ **세 값이 갈린다.** 마감 조건: 공식전 표본으로 점유·패스량을 2경기 이상 확인해 Counter/Balanced/Short Passing 중 결정.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(22,'MdhMmXmVdUc','team_axis',NULL,'CHE',NULL,NULL,'formation','3-4-2-1','「deploy Chelsea in his preferred **3-4-2-1** formation」(선호하는 **3-4-2-1**로 배치한다)','HELD','✅ 이미 일치 — regime 2 `projected` = 3-4-2-1. 재판정 조건: 인게임 포메이션은 슬롯 제약으로 5-4-1을 채택 중이므로(reference 행), FC27에서 3-4-2-1 와이드가 FB 슬롯을 받으면 재매핑.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(23,'MdhMmXmVdUc','limit',NULL,NULL,NULL,NULL,'pressing','즉시 카운터프레스를 핵심 원칙으로 요구하나 FC26은 Aggressive에 오프사이드 트랩이 묶여 있어 분리 조절 불가','「**Immediate counter-pressing after losing possession will be a key principle**」(**볼을 잃은 즉시 카운터프레스가 핵심 원칙**이다)','HELD','✅ `reproduction_limits`에 이미 등록된 한계다 — 「압박 강도·트리거 슬라이더가 없다. Aggressive는 「즉시 카운터프레스+오프사이드 트랩」 묶음이라 분리 조절 불가」. 새 한계가 아니므로 행 추가 없음. 재판정 조건: FC27이 압박 트리거 축을 분리하면 재검토(09-18 얼리액세스 후).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(24,'ETMJDrEH2Pk','team_axis',NULL,'LIV',NULL,NULL,'build_up_style','Counter','「The **build-up style would be set to counter**, but that does not mean abandoning possession」(**빌드업 스타일은 카운터로 설정**되지만 점유 포기를 뜻하진 않는다)','PENDING','⭐ 팀 설정 3축은 실측이 값을 갖지 않아 전술 분석이 1차 소스다(docs/30 7단계). 현행 regime 3 `projected`는 **Balanced**이고 이 자료는 **Counter**다 ⇒ 갈린다. ⛔ 단 **부임 전 추측판**이라 단독 근거로 부족하다. 마감 조건: 이라올라 체제 공식전 실측(점유율·패스량·시퀀스당 패스)을 2경기 이상 확보해 판정. LIV는 이미 UCL MD1(ATM전) 실측이 있으므로 PL 표본만 더 쌓이면 된다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(25,'ETMJDrEH2Pk','team_axis',NULL,'LIV',NULL,NULL,'defensive_approach','High','「the approach would be **set to high**, with Iraola demanding aggressive pressing」(접근은 **하이**로 설정되고 이라올라는 적극적 압박을 요구한다)','HELD','✅ 이미 일치 — regime 3 `projected` da=High · line=64. 재판정 조건: 안필드 ATM전 실측 PPDA 16.44(백3 매치업 실패)가 반복되면 High 유지가 맞는지 재검토.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(26,'ETMJDrEH2Pk','limit',NULL,NULL,NULL,NULL,'pressing','압박 트리거 4종 특정 — 백패스 · 나쁜 첫 터치 · 고립된 측면으로의 패스 · 상대가 자기 골대를 보고 받는 순간','「Common triggers would include **backwards passes, poor first touches, passes into [isolated] wide areas, or moments when the opponent receives a pass facing their own goal**」(흔한 트리거는 **백패스, 나쁜 첫 터치, 고립된 측면으로의 패스, 상대가 자기 골대를 보고 패스를 받는 순간**이다)','HELD','✅ `reproduction_limits`에 「압박 트리거·카운터프레스 강도 슬라이더가 없다」로 이미 등록된 한계다 — 새 행 추가 없음. ⭐ 다만 **트리거를 4종으로 나열한 유일한 자료**라 실축 판정(왜 그 순간 압박이 터졌나)의 대조표로는 값이 있다. 재판정 조건: FC27이 압박 트리거 축을 분리하면 재검토(09-18 얼리액세스).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(27,'ETMJDrEH2Pk','role',47,NULL,'fb_att_wb','Attack',NULL,NULL,'「The full-backs being Kerkez and Frimpong would operate as **attacking wing-backs with an attack focus**」(케르케즈와 프림퐁은 **어택 포커스의 공격 윙백**으로 뛴다)','REJECTED','⛔ **양쪽 풀백 동시 Attack은 실측과 어긋난다.** 26/27 공식전 실측(obs#773 재집계)은 케르케즈 `fb_att_wb/**Support**` .9489 · 프림퐁 `fb_att_wb/**Support**` .9387로 **둘 다 Support**다 — 포커스 층에서 갈린다. 또한 **부임 전 추측판**이라 실측을 덮을 근거가 못 된다(docs/30 7단계 ⑷ 반박권 행사). ⭐ 다만 「양쪽 동시 전진」 주장 자체는 에메리 축의 C2/C6(풀백 한 명씩 전진)을 이라올라 축에 옮기면 안 된다는 점을 상기시킨다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(28,'11kt8KYhtvw','team_axis',NULL,'ATM',NULL,NULL,'formation','4-4-2','「Atletico Madrid **primarily line up in a 4-4-2 shape** under Diego Simeone」(시메오네 아래 ATM은 **주로 4-4-2로 선다**)','HELD','⭐ **HANDOFF 미해결 1(ATM 포메이션 표기 충돌)의 4-4-2 축을 강화**한다 — 우리·El Desmarque·COPE가 4-4-2, Infobae가 4-3-3으로 갈렸고 obs#454·#508이 4-4-2 방향이었다. ⛔ 그러나 **25/26 자료**이고, 26/27에는 3-4-2-1(UCL MD1 안필드)·3-5-2(리버풀전 실측) 기록이 있어 **시즌이 다르다** ⇒ 처방 변경 없음. 재판정 조건: 26/27 라리가 표본에서 포메이션 상수를 재산출(현재 ATM 실측 4-1-4-1 기하가 더 가까워 처방 미이관 상태).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(29,'11kt8KYhtvw','team_axis',NULL,'ATM',NULL,NULL,'build_up_style','Counter','「The build-up approach... is **set to counter**, encouraging constant forward runs and quick vertical progression」(빌드업 접근은 **카운터로 설정**돼 지속적 전진 런과 빠른 수직 전진을 장려한다)','PENDING','⭐ 팀 설정 3축은 실측이 값을 갖지 않아 전술 분석이 1차 소스다(docs/30 7단계). ATM은 `team_tactic_setups`에 `measured` 행만 있고 **bu·da·line이 전부 NULL**이다 ⇒ 채울 근거가 필요한 상태. ⛔ 단 25/26 자료라 26/27에 그대로 옮길 수 없다. 마감 조건: 26/27 라리가 실측(점유율·시퀀스당 패스·롱볼 비율)으로 교차검증 후 등록.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(30,'11kt8KYhtvw','limit',NULL,NULL,NULL,NULL,'pressing','상시 압박이 아니라 간헐적·타이밍 기반 함정 — 상대를 중앙으로 유도한 뒤 수적으로 덮친다','「Rather than pressing constantly, they use **sporadic well-timed pressure to set traps, inviting opponents into central areas, and collapsing on them with numbers**」(상시 압박 대신 **간헐적이고 타이밍 좋은 압박으로 함정을 놓아 상대를 중앙으로 초대한 뒤 수적으로 덮친다**)','PENDING','⭐⭐ **HANDOFF 미해결 1의 「저블록 서사 ↔ 압박 상수(PPDA 8.26) 불일치」를 설명할 후보다** — 상시 압박이 아니라 간헐적 함정이면 PPDA가 중간값으로 나온다. ⛔ FC26에는 압박 트리거 축이 없어 설정으로 못 옮긴다(`reproduction_limits` pressing 3행). ⇒ **실축 해석 근거**로는 채택 후보, **구현 주장으로는 한계 축**. 마감 조건: 알론소 「trampa pentagonal」(qkcMoU2khyk)과 함께 「압박 형태」를 reproduction_limits 4번째 pressing 행으로 묶어 등록할지 판단.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(31,'11kt8KYhtvw','instruction',NULL,'ATM',NULL,NULL,'wide_asymmetry','양 윙어 비대칭 — 한쪽은 안으로 접혀 추가 미드필더, 다른 쪽은 폭 유지','「**One often tucks inside to operate almost as an additional midfielder**... while **the other stays wide to stretch the pitch**」(**하나는 자주 안으로 접혀 사실상 추가 미드필더로** 뛰고… **다른 하나는 넓게 머물러 피치를 늘린다**)','HELD','✅ 우리 **C6(해방 사이드 비대칭)·docs/20 ⑨(윙 혼잡 회피 — 같은 쪽 와이드가 터치라인을 점유하면 풀백은 전진하지 않는다)**가 이미 정본화한 구조다. ATM 축에서 독립 서술된 것이라 **규칙의 외부 확인**이지 새 주장이 아니다 ⇒ 변경 없음. ⭐ 재판정 조건: obs#768로 AVL의 해방 사이드가 좌→우로 뒤집혀 **C2/C6 재판정이 대기 중**이다(할 일 20) — 그 판정에 이 서술을 대조군으로 쓴다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(32,'cgk1tLlUK_o','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(33,'vS1E2UKG4aQ','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(34,'67TNBKbdUDw','limit',NULL,NULL,NULL,NULL,'pressing','압박 트리거·레인·배정이 상대 빌드업 형태에 종속된다 — 상대가 예상 밖 구조(백5)를 쓰면 압박 전체가 어긋난다','「**Liverpool''s pressing structure is built around recognizing where the opposition wants to build from**. You have your **triggers**, your **pressing lanes**, your **assignments**, and suddenly Atletico give you a different structure」(**리버풀 압박 구조는 상대가 어디서 빌드업하려는지 인식하는 데 기반한다** — **트리거·압박 레인·배정**이 있는데 갑자기 다른 구조를 받는다)','HELD','✅ `reproduction_limits`에 「압박 트리거·카운터프레스 강도 슬라이더가 없다」로 이미 등록된 한계다 — 새 행 추가 없음. ⭐ 다만 **「상대 형태 종속성」은 기존 서술에 없던 층**이다: FC26의 수비 접근 4종은 **상대 포메이션에 반응하지 않는다**. 재판정 조건: FC27이 상대별 압박 설정을 주면 재검토(09-18).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(35,'67TNBKbdUDw','team_axis',NULL,'LIV',NULL,NULL,'build_up_style','Counter','「**Liverpool didn''t dominate the football, they dominated the dangerous moments**」(리버풀은 볼을 지배한 게 아니라 **위험한 순간을 지배했다**) · 「점유 45% ↔ xG 1.68 대 0.81 · 슛 14 대 9 · 박스 터치 31 대 18」','PENDING','⭐ ETMJDrEH2Pk(Brom Squad Gaming)도 이라올라 빌드업을 **Counter**로 지목했고, 이 영상은 **실측 수치로 같은 방향을 지지**한다(점유 45%인데 침투 지표는 압도). 현행 regime 3 `projected`는 **Balanced**다. ⇒ 두 소스가 수렴하므로 마감에 가까워졌다. 마감 조건: PL 공식전 표본 1건 더(점유·xG·박스 터치) 확인 후 `team_tactic_setups` 갱신.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(36,'6Tytmc_UKek','limit',NULL,NULL,NULL,NULL,'formation','상대(포레스트)가 무공 시 5-4-1 ↔ 5-3-2를 상황에 따라 오간다 — 국면별 포메이션 전환','「Out of possession they are **dropping into a 5-4-1**… the other option… **5-3-2 which keeps Gibbs-White central off the striker**」(무공 시 **5-4-1**로 내려앉거나, 다른 옵션으로 **5-3-2로 깁스-화이트를 스트라이커 아래 중앙에** 둔다)','HELD','✅ `reproduction_limits`에 「FC26은 국면별 포메이션을 갖지 않는다 — 빌드업 스타일·수비접근이 국면을 대신한다」로 이미 등록된 한계다. 상대팀 사례라 우리 처방 대상도 아니다 ⇒ 변경 없음. ⭐ 재판정 조건: 상대팀 프리셋을 별도로 만들 축을 열지 여부(현재 우리는 상대팀 전술을 DB에 담지 않는다).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(37,'6Tytmc_UKek','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(38,'gR_pzueBN2s','focus',51,NULL,NULL,'Attack',NULL,NULL,'「**we have midfielders that naturally they are going to arrive to the box**… it''s good that we can **benefit offensively from those situations**」(**자연스럽게 박스에 도착하는 미드필더들이 있다**… 그 상황에서 **공격적 이득을 보는 것이 좋다**)','PENDING','⭐ 감독 1차 발언으로 **중앙 미드의 박스 도착을 구조적으로 허용**한다고 명시했다(흐라벤베르흐·소보슬라이·맥 알리스터 3명 지목). 포커스 층 주장이라 역할은 건드리지 않는다. ⛔ 소보슬라이는 표본 감사에서 **RDM 순수 2경기 166분**으로 얇고(obs#772), CAM 3경기 270분이 더 크다 ⇒ **슬롯 확정이 선행 조건**이다(할 일 24). 마감 조건: 소보슬라이 축 정리 후 포커스 재산출.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(39,'gR_pzueBN2s','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(40,'HJnDujuUi2o','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(41,'3E_7R6so73Q','limit',NULL,NULL,NULL,NULL,'rotation','ATM 후반 부진의 원인은 체력 저하가 아니다 — 감독이 명시적으로 부인하고 「못 뛴 것」으로 귀속','「**siempre es normal que cuando parecería que en el segundo tiempo no hace lo mismo que en el primero, aparece que no están bien físicamente**… **jugaste bien, el segundo tiempo jugaste mal**」(**후반에 전반과 같지 않아 보이면 늘 체력 얘기가 나온다**… **잘 뛰었다가 후반엔 못 뛴 것**이다)','HELD','⭐ `reproduction_limits`의 `rotation` 축(「주행 부하·일정 밀도에 따른 강도 조절 — 시즌 누적 피로는 게임에 있으나 전술 설정 축이 아니다」)에 **반대 방향 근거**를 더한다: 감독 1차 발언이 **체력 가설을 기각**했으므로 ATM 후반 붕괴를 피로 축으로 모델링하면 안 된다. 기존 한계 행을 바꾸지 않고 해석만 고정한다 ⇒ 변경 없음. 재판정 조건: 후반 실점 시계열이 실측으로 쌓이면 국면(리드 관리) 축으로 재검토(obs#514 계열).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(42,'xBiwApe6wfk','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(43,'f9v4wwLfEeE','instruction',NULL,'CHE',NULL,NULL,'link_pair','콜 파머–모건 로저스 연결을 감독이 「우리가 가진 강점」으로 명시 — 좌(로저스)·우(파머) 연결축','「**we have a good partnership there**… **It''s a strength that we have**」(**거기 좋은 파트너십이 있다**… **우리가 가진 강점이다**) · 「even **before playing together, they were so connected**」(**함께 뛰기 전부터 둘은 매우 연결돼 있었다**)','HELD','⭐ 1차 발언으로 **좌·우 연결축을 감독이 인정**했다. 우리 측 현황과 정합한다 — 로저스 `#421` LM `wm_wideplm/Attack`(좌) · 파머 `#484` RAM `cam_playmaker/Roaming`(우, obs#770에서 ST→RAM 재선언). 둘 다 안쪽 지향 창조형이라 **연결이 성립하는 조합**이다 ⇒ 처방 변경 없음. ⚠️ 재판정 조건: MdhMmXmVdUc(Brom Squad)가 지적한 **「두 10번을 같은 유형으로 두면 안 된다」**(obs#464 CAM 유형 함수)와 충돌하는지 — 로저스가 CAM 슬롯으로 올라오면 파머와 유형이 겹칠 수 있다. CHE 슬롯 확정 시 재검토.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(44,'x6RV_fk2DVc','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(45,'yMmxDTdffv4','team_axis',NULL,'AVL',NULL,NULL,'build_up_style','Balanced','「We get to the **final third and none of them take risk**… **We''re so safe** — but **we are so risky on the edge of our own box**」(**파이널 서드에선 아무도 리스크를 안 진다**… **너무 안전하다** — 그런데 **자기 박스 앞에서는 너무 위험하다**)','PENDING','⭐ 팀 설정 3축은 실측이 값을 갖지 않아 전술 분석이 1차 소스다(docs/30 7단계). 현행 AVL regime 1은 **Short Passing**(20/22행이 이 값)인데, 「후방에서 위험한 잔기술 + 전방에서 안전한 패스」는 **짧은 패스 지향의 부작용**을 서술한 것으로 읽힌다. ⛔ 단 이 영상은 **경기 직후 감정 반응 1건**이라 단독 근거로 부족하다. 마감 조건: 같은 지적이 2소스 이상(§11-3의 「폭 미활용·안전함」 축과 함께) 반복되고, 실측(파이널 서드 패스 방향·박스 진입 수)으로 교차 확인될 것.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(46,'yMmxDTdffv4','instruction',NULL,'AVL',NULL,NULL,'left_cover','우측 해방(맥긴 winger) 구성에서 좌측 풀백이 1대1로 고립된다 — 좌측 더블링 부재가 후반 붕괴 경로','「**he was so isolated on that one side**… It was **him one v one. Where was McGinn?** Where''s the player **doubling up and helping out** Maatsen」(**그 사이드에서 너무 고립됐다**… **1대1이었다. 맥긴은 어디 있었나?** **더블링해 돕던** 선수는 어디 있었나)','PENDING','⭐⭐ **obs#768의 직접 후속이다** — 맥긴 RM을 `wm_winger/Attack`(뱅크 **0.00**)으로 교정하고 헤밍스 LM을 `wm_widemid/Support`(뱅크 0.60)로 둔 구성에서 **좌측 커버 공백은 구조적 귀결**이다. 이 영상이 그 귀결을 **실전에서 관측**했다(같은 경기 report 39). ⇒ **C2/C6 재판정(할 일 20)의 실전 증거로 편입.** 마감 조건: 할 일 20 판정 시 이 관찰을 obs#443(윙어 쪽 풀백 절제) ↔ obs#95(해방 사이드 풀백 전진) 중 어느 쪽을 지지하는지 판정 — 현재로선 **「윙어 쪽이 아니라 반대쪽이 비었다」**이므로 단순 대입이 안 된다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(47,'tbyZNcjQZTQ','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(48,'pO6Pxey6GY0','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(49,'m4z54R9Xrlk','focus',30,NULL,NULL,'Balanced',NULL,NULL,'「**Hemmings could have put us a few more up**… **he''s building into it as well**」(**헤밍스가 몇 골 더 넣을 수도 있었다**… 그도 **점점 자리를 잡아가는 중**이다)','HELD','⭐ obs#768에서 헤밍스 LM을 **`wm_widemid/Support`(뱅크 0.60)** 로 처방했는데, 이는 **실측 argmax `wm_winger/Balanced` .6759(1위)를 Δ.0137 무결정 구간에서 구조(C1 두 줄 4)로 tie-break한 결과**다. 이 영상은 그의 **공격 기여**를 관측하므로 argmax 쪽(winger/Balanced) 근거가 된다. ⛔ 그러나 팬 관점 1건이고 **C1 뱅크는 여전히 좌측이 대야 한다**(맥긴 RM winger/Attack = 0.00) ⇒ 처방 변경 없음. **재판정 조건: 할 일 20(C2/C6 재판정)에서 뱅크 부담을 다른 칸으로 옮길 수 있게 되면 즉시 `winger/Balanced`로 복귀 검토.**','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(50,'8RE9ovIglEw','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(51,'7Afj8XxiVW0','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(52,'tq5_q0cl5hM','team_axis',NULL,'AVL',NULL,NULL,'build_up_style','Balanced','「**They don''t have to dominate possession, but when they get possession, they''ve got a purpose with it**. And **they were missing that a little bit this season**」(**점유를 지배할 필요는 없지만 점유하면 목적이 있다**. 그런데 **이번 시즌엔 그게 조금 없었다**)','PENDING','⭐ `yMmxDTdffv4`(UTV, 「파이널 서드에서 리스크를 안 진다」)와 **같은 결손을 다른 방향에서 진술**한 2번째 소스다. 현행 AVL regime 1은 `Short Passing` 20/22행. ⇒ 마감 조건에 한 걸음 다가섰다(2소스 확보). ⏰ 남은 조건: **실측 교차검증** — 파이널 서드 패스 방향·박스 진입 수·시퀀스당 패스를 브뤼헤전(승)과 포레스트전(패)으로 나눠 대조. 승패로 갈리면 「목적성」은 결과 서술이지 설정 축이 아닐 수 있다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
